def get_diagonal_type(positions):
    """
    Determine which diagonal type these positions are on.
    Returns: 'main' if all have same x-y, 'anti' if all have same x+y, None other.
    """
    if len(positions) <= 1:
        return None

    x_minus_y = set(pos[0] - pos[1] for pos in positions)
    x_plus_y = set(pos[0] + pos[1] for pos in positions)

    if len(x_minus_y) == 1 and len(x_plus_y) > 1:
        return 'main'
    elif len(x_plus_y) == 1 and len(x_minus_y) > 1:
        return 'anti'
    else:
